const prompt = $json.data;
const ctx = $('Prepare Get-Prompt Input').first().json._ctx;
const model = (prompt.model_compatibility && prompt.model_compatibility[0]) || 'claude-opus-4-8';
const userPayload = {
  topic: ctx.topic, intended_angle: ctx.intended_angle || null, target_duration_seconds: ctx.target_duration_seconds || null,
  channel: {
    niche: ctx.niche || null, target_audience: ctx.target_audience || null, script_tone: ctx.script_tone || null,
    hook_style: ctx.hook_style || null, cta_type: ctx.cta_type || null, cta_style: ctx.cta_style || null,
    content_pillars: ctx.content_pillars || [], strategy_notes: ctx.strategy_notes || null
  },
  speaking_rate_wpm: ctx.speaking_rate_wpm || 155,
  research_package: ctx.research_package
};
const schema = {"title":"YouTube Script","description":"Structured output of the script-generation (and script-revision) LLM call — the JSONB stored in script_versions.content. Every factual narration-bearing unit must carry source_ids/claim_ids copied exactly from the approved research package; `cited_source_ids`/`cited_claim_ids` must list the union of every id referenced anywhere in this document — checked by script_grounding_report() against `sources`/`research_claims`, never trusted from the LLM. Structured enough for later TTS/visual-planning/captioning/rendering stages without redesign; nothing here fetches or generates media — visual/on-screen-text fields are planning metadata only. See docs/architecture/script-pipeline.md#structured-script-contract.","$defs":{"narrationUnit":{"type":"object","additionalProperties":false,"required":["narration","source_ids","claim_ids"],"properties":{"narration":{"type":"string","description":"Natural spoken narration text. May be an empty string only for a purely visual beat — deterministic QC penalizes this."},"source_ids":{"type":"array","items":{"type":"string"},"description":"source_id values (from the approved research package) that ground any factual content in this unit's narration."},"claim_ids":{"type":"array","items":{"type":"string"},"description":"claim_id values (from the approved research package) that ground any factual content in this unit's narration."},"pronunciation_notes":{"type":"array","description":"Acronyms, uncommon names, technical terms, or foreign words in this unit's narration that Step 8 (TTS) should be aware of. No pronunciation conversion happens here — just preserved for later use.","items":{"type":"object","additionalProperties":false,"required":["term"],"properties":{"term":{"type":"string"},"note":{"type":["string","null"],"description":"e.g. a phonetic hint or 'pronounced as written' — free text, no fixed IPA/phoneme system enforced."}}}},"estimated_duration_seconds":{"type":["number","null"]}}},"section":{"type":"object","additionalProperties":false,"required":["section_id","section_type","narration","source_ids","claim_ids"],"properties":{"section_id":{"type":"string","description":"Stable within this script version — Step 8/9 workflows depend on it. Not derived from array position."},"section_type":{"type":"string","enum":["explainer","narrative","comparison","statistic_highlight","opinion","commentary","transition","recap"],"description":"'opinion' and 'commentary' are the only types exempt from the missing-reference deterministic check — see docs/architecture/script-pipeline.md#unsupported-fact-detection."},"heading":{"type":["string","null"]},"narration":{"type":"string"},"purpose":{"type":["string","null"],"description":"Why this section exists in the narrative — retention/pacing rationale, not shown to the viewer."},"source_ids":{"type":"array","items":{"type":"string"}},"claim_ids":{"type":"array","items":{"type":"string"}},"visual_direction":{"type":["string","null"]},"b_roll_queries":{"type":"array","items":{"type":"string"}},"on_screen_text":{"type":["string","null"],"description":"Concise — a statistic, key term, date, or name, not a narration duplicate. Deterministic QC flags entries over ~60 characters."},"transition":{"type":["string","null"],"description":"How this section transitions to the next — deterministic QC flags identical transitions repeated across consecutive sections."},"sound_design_notes":{"type":["string","null"]},"pronunciation_notes":{"$ref":"#/$defs/narrationUnit/properties/pronunciation_notes"},"estimated_duration_seconds":{"type":["number","null"]}}},"hook":{"type":"object","additionalProperties":false,"required":["opening_line","viewer_promise","transition_into_body","narration","source_ids","claim_ids"],"properties":{"opening_line":{"type":"string"},"tension_or_question":{"type":["string","null"]},"viewer_promise":{"type":"string","description":"What the viewer gets for staying — must be honest, not a fabricated stake."},"curiosity_loop":{"type":["string","null"]},"transition_into_body":{"type":"string"},"narration":{"type":"string","description":"The hook's full spoken narration (opening_line + tension_or_question + viewer_promise + curiosity_loop + transition_into_body, composed into natural speech). Factual assertions here are NOT exempt from grounding — see docs/architecture/script-pipeline.md#hook-structure."},"source_ids":{"type":"array","items":{"type":"string"}},"claim_ids":{"type":"array","items":{"type":"string"}},"pronunciation_notes":{"$ref":"#/$defs/narrationUnit/properties/pronunciation_notes"},"estimated_duration_seconds":{"type":["number","null"]}}},"cta":{"type":"object","additionalProperties":false,"required":["cta_type","narration"],"properties":{"cta_type":{"type":"string","enum":["subscribe","comment","affiliate_link","newsletter","next_video","product","community"],"description":"Must match the channel's configured CTA goal — the generator scripts only the configured type, never an unconfigured monetization offer."},"narration":{"type":"string"},"source_ids":{"type":"array","items":{"type":"string"}},"claim_ids":{"type":"array","items":{"type":"string"}},"estimated_duration_seconds":{"type":["number","null"]}}}},"type":"object","additionalProperties":false,"required":["title_concept","target_duration_seconds","hook","intro","sections","outro","cta","estimated_word_count","estimated_duration_seconds","cited_source_ids","cited_claim_ids"],"properties":{"title_concept":{"type":"string","description":"A working title/concept — not final YouTube metadata (title/description/tags are a later step)."},"target_duration_seconds":{"type":"number"},"hook":{"$ref":"#/$defs/hook"},"intro":{"$ref":"#/$defs/narrationUnit"},"sections":{"type":"array","minItems":1,"items":{"$ref":"#/$defs/section"}},"outro":{"$ref":"#/$defs/narrationUnit"},"cta":{"$ref":"#/$defs/cta"},"estimated_word_count":{"type":"integer","description":"The LLM's own estimate — deterministic QC independently recomputes this from narration_text and compares."},"estimated_duration_seconds":{"type":"number","description":"The LLM's own estimate — not trusted alone; deterministic QC computes an independent word-count-based estimate and penalizes large deviations between the two."},"cited_source_ids":{"type":"array","description":"Union of every source_id referenced anywhere in this document (hook, intro, every section, outro, cta). Checked against `sources` by script_grounding_report() — never trusted as-is.","items":{"type":"string"}},"cited_claim_ids":{"type":"array","description":"Union of every claim_id referenced anywhere in this document. Checked against `research_claims` by script_grounding_report() — never trusted as-is.","items":{"type":"string"}}}};
return [{ json: {
  ctx, model, prompt_version_id: prompt.prompt_version_id,
  requestBody: {
    model, max_tokens: 8192,
    system: prompt.content,
    messages: [{ role: 'user', content: JSON.stringify(userPayload) }],
    output_config: { format: { type: 'json_schema', schema } }
  }
} }];

const resp = $input.first().json;
const ctx = $('Prepare Anthropic Request').first().json.ctx;
const model = $('Prepare Anthropic Request').first().json.model;
const textBlock = (resp.content || []).find((b) => b.type === 'text');
let result = null; let parse_failed = true;
if (textBlock) { try { result = JSON.parse(textBlock.text); parse_failed = false; } catch (e) { parse_failed = true; } }
return [{ json: { parse_failed, ctx, model, script: result, usage: resp.usage || {}, provider_request_id: resp.id || null, _raw_text: textBlock ? textBlock.text : null, repaired: false } }];

const p = $('Parse Response').first().json;
const orig = $('Prepare Anthropic Request').first().json.requestBody;
const repairMessages = orig.messages.concat([
  { role: 'assistant', content: p._raw_text || '' },
  { role: 'user', content: 'Your previous response was not valid JSON matching the required schema. Return ONLY the corrected JSON object matching the schema -- no prose, no markdown fences.' }
]);
return [{ json: { ctx: p.ctx, model: p.model, requestBody: { ...orig, messages: repairMessages } } }];

const resp = $input.first().json;
const ctx = $('Prepare Repair Request').first().json.ctx;
const model = $('Prepare Repair Request').first().json.model;
const textBlock = (resp.content || []).find((b) => b.type === 'text');
let result = null; let parse_failed = true;
if (textBlock) { try { result = JSON.parse(textBlock.text); parse_failed = false; } catch (e) { parse_failed = true; } }
return [{ json: { parse_failed, ctx, model, script: result, usage: resp.usage || {}, provider_request_id: resp.id || null, repaired: true } }];

const ctx = $json.ctx;
return [{ json: {
  success: false, data: null,
  error: { code: 'SCRIPT_SCHEMA_INVALID', message: 'LLM response was not valid structured JSON, even after one repair attempt', retryable: true, error_id: null },
  runtime: { channel_id: ctx.channel_id, workflow_run_id: ctx.workflow_run_id, content_project_id: ctx.content_project_id, correlation_id: null }
} }];

const j = $('Parsed Result').first().json; const ctx = j.ctx;
const inputTokens = j.usage.input_tokens || 0;
const outputTokens = j.usage.output_tokens || 0;
const inputCost = (inputTokens / 1000000) * 5;
const outputCost = (outputTokens / 1000000) * 25;
const totalCost = Math.round((inputCost + outputCost) * 1000000) / 1000000;
return [{ json: {
  channel_id: ctx.channel_id, content_project_id: ctx.content_project_id, workflow_run_id: ctx.workflow_run_id, workflow_step_id: null,
  provider: 'anthropic', service_type: 'llm', model: j.model,
  quantity: inputTokens + outputTokens, unit: 'token', unit_price_usd: null,
  total_cost_usd: totalCost, provider_request_id: j.provider_request_id, estimated: false, metadata: { repaired: !!j.repaired }
} }];

const j = $('Parsed Result').first().json; const ctx = j.ctx;
return [{ json: {
  channel_id: ctx.channel_id, workflow_run_id: ctx.workflow_run_id, content_project_id: ctx.content_project_id,
  research_package_id: ctx.research_package && ctx.research_package.research_package_id, generation_prompt_version_id: ctx.prompt_version_id,
  content: j.script,
  estimated_duration_seconds: j.script ? j.script.estimated_duration_seconds : null,
  provider: 'anthropic', model: j.model, provider_request_id: j.provider_request_id,
  revision_trigger: 'initial_generation', revision_reason: null
} }];

const inp = $input.first().json;
const s = inp.content;
const parts = [s.hook && s.hook.narration, s.intro && s.intro.narration];
for (const sec of (s.sections || [])) parts.push(sec.narration);
parts.push(s.outro && s.outro.narration, s.cta && s.cta.narration);
inp.narration_text = parts.filter((p) => p && String(p).trim() !== '').join('\n\n');
return [{ json: inp }];
